    });

    expect(sql.clauseQueries[0]!.statement).toContain("c.spec_id ~ '^AUTO-BAR-R-[0-9]+-P-[0-9]{3,}$'");
    expect(writeFor('AUTO-BAR-R-1-P-001')).toMatchObject({ lifecycleStatus: 'superseded', sourceBar: null });
  });

